<script>(function(){const btn=document.getElementById('menuBtn'),menu=document.getElementById('menu');btn&&btn.addEventListener('click',()=>menu.classList.toggle('open'));menu&&menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>menu.classList.remove('open')));const slides=[...document.querySelectorAll('.hero-slide')],dots=[...document.querySelectorAll('.slide-dot')];if(slides.length>1){let current=0,timer;function show(i){current=(i+slides.length)%slides.length;slides.forEach((s,n)=>s.classList.toggle('active',n===current));dots.forEach((d,n)=>d.classList.toggle('active',n===current))}function restart(){clearInterval(timer);timer=setInterval(()=>show(current+1),5000)}dots.forEach(d=>d.addEventListener('click',()=>{show(Number(d.dataset.go));restart()}));restart()}})();</script>
